import unittest
from collections import OrderedDict

from solution import render_status


class RenderStatusTests(unittest.TestCase):
    def setUp(self):
        self.fields = {
            'machine': 'build-01',
            'account': 'forge',
            'platform': 'linux',
            'interpreter': 'python',
        }

    def test_plain_output_has_exact_order_and_trailing_newline(self):
        result = render_status(self.fields, use_color=False)
        self.assertEqual(
            result,
            'Machine: build-01\nAccount: forge\nPlatform: linux\nInterpreter: python\n',
        )
        self.assertNotIn('\x1b', result)

    def test_color_wraps_only_values(self):
        self.assertEqual(
            render_status(self.fields),
            'Machine: \x1b[96mbuild-01\x1b[0m\n'
            'Account: \x1b[92mforge\x1b[0m\n'
            'Platform: \x1b[91mlinux\x1b[0m\n'
            'Interpreter: \x1b[95mpython\x1b[0m\n',
        )

    def test_mapping_input_order_does_not_change_output_order(self):
        fields = OrderedDict([
            ('interpreter', 'p'), ('platform', 'x'), ('account', 'a'), ('machine', 'm')
        ])
        self.assertEqual(
            render_status(fields, use_color=False),
            'Machine: m\nAccount: a\nPlatform: x\nInterpreter: p\n',
        )

    def test_empty_values_are_valid_and_input_is_unchanged(self):
        fields = {key: '' for key in self.fields}
        snapshot = fields.copy()
        result = render_status(fields, use_color=False)
        self.assertEqual(result, 'Machine: \nAccount: \nPlatform: \nInterpreter: \n')
        self.assertEqual(fields, snapshot)

    def test_invalid_fields_and_color_flag(self):
        invalid = [
            None,
            [],
            {'machine': 'm', 'account': 'a', 'platform': 'p'},
            {**self.fields, 'extra': 'x'},
            {**self.fields, 'machine': 1},
            {1: 'm', 'account': 'a', 'platform': 'p', 'interpreter': 'i'},
        ]
        for fields in invalid:
            with self.subTest(fields=fields):
                with self.assertRaises(ValueError):
                    render_status(fields)
        for flag in (0, 1, None, 'yes'):
            with self.subTest(flag=flag):
                with self.assertRaises(ValueError):
                    render_status(self.fields, use_color=flag)


if __name__ == '__main__':
    unittest.main()

